import{_ as a,c as t,o as i,a2 as n}from"./chunks/framework.mqLGQ42V.js";const f=JSON.parse('{"title":"设计模式对比动画模式 (Design vs Animate Mode) - Rive 编辑器","description":"基础概念 (Fundamentals) Rive 编辑器具有两种截然不同的模式：设计 (Design) 和动画 (Animate)。在不同模式间切换会改变界面显示的工具和选项。","frontmatter":{"title":"设计模式对比动画模式 (Design vs Animate Mode) - Rive 编辑器","description":"基础概念 (Fundamentals) Rive 编辑器具有两种截然不同的模式：设计 (Design) 和动画 (Animate)。在不同模式间切换会改变界面显示的工具和选项。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 设计模式对比动画模式"}]]},"headers":[],"relativePath":"editor/fundamentals/design-vs-animate-mode.md","filePath":"editor/fundamentals/design-vs-animate-mode.md","lastUpdated":1774867914000}'),o={name:"editor/fundamentals/design-vs-animate-mode.md"};function s(r,e,d,m,c,l){return i(),t("div",null,[...e[0]||(e[0]=[n('<p>基础概念 (Fundamentals)</p><h1 id="设计模式对比动画模式-design-vs-animate-mode" tabindex="-1">设计模式对比动画模式 (Design vs Animate Mode) <a class="header-anchor" href="#设计模式对比动画模式-design-vs-animate-mode" aria-label="Permalink to &quot;设计模式对比动画模式 (Design vs Animate Mode)&quot;">​</a></h1><p>Rive 编辑器具有两种截然不同的模式：设计 (Design) 和动画 (Animate)。在不同模式间切换会改变界面显示的工具和选项。</p><h2 id="​-设计模式-design-mode" tabindex="-1"><a href="#design-mode">​</a> 设计模式 (Design Mode) <a class="header-anchor" href="#​-设计模式-design-mode" aria-label="Permalink to &quot;[​](#design-mode) 设计模式 (Design Mode)&quot;">​</a></h2><p>使用设计模式为动画准备图形。在这里，你可以使用 Rive 的<a href="./../interface-overview/toolbar">工具</a>设计图形、<a href="./importing-assets">导入外部素材</a>，或者是通过<a href="./../manipulating-shapes/bones">骨骼</a>、<a href="./origin-freeze">变换空间</a>、<a href="/docs/editor/layouts/overview">布局</a>、<a href="/docs/editor/manipulating-shapes/joysticks">摇杆</a>及<a href="/docs/editor/constraints/overview">约束</a>进行绑定。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 设计模式界面) 设计模式是任何尚未创建动画的文件的默认模式。该模式存在的原因是 Rive 允许在一个画板上添加多个动画，因此你需要一个地方来统一设置和创建图形基础。</p></blockquote><h2 id="​-动画模式-animate-mode" tabindex="-1"><a href="#animate-mode">​</a> 动画模式 (Animate Mode) <a class="header-anchor" href="#​-动画模式-animate-mode" aria-label="Permalink to &quot;[​](#animate-mode) 动画模式 (Animate Mode)&quot;">​</a></h2><p>使用 <a href="/docs/editor/animate-mode/overview">动画模式</a> 为你的画板创建所有的 <a href="/docs/editor/state-machine/states">状态 (States)</a> 和 <a href="/docs/editor/state-machine/overview">状态机 (State Machine)</a>。 当你切换到动画模式时，UI 会更新并显示与<a href="/docs/editor/fundamentals/artboards#active-artboard">活动画板</a>相关联的时间轴列表和状态机。同时，<a href="/docs/editor/interface-overview/inspector">检查器 (Inspector)</a> 也会在所有可动画化的属性旁显示关键帧按钮。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 动画模式界面) 在动画列表中选择任何“时间轴动画 (Animation)”将调出时间轴视图，而选择“状态机 (State Machine)”则会将时间轴替换为图表(Graph)视图。</p></blockquote><h2 id="​-在动画模式下创建素材-creating-assets-in-animate-mode" tabindex="-1"><a href="#creating-assets-in-animate-mode">​</a> 在动画模式下创建素材 (Creating Assets in Animate Mode) <a class="header-anchor" href="#​-在动画模式下创建素材-creating-assets-in-animate-mode" aria-label="Permalink to &quot;[​](#creating-assets-in-animate-mode) 在动画模式下创建素材 (Creating Assets in Animate Mode)&quot;">​</a></h2><p>尽管存在不同的模式，但在两种模式下都可以创建和更改图形，但请务必记住以下几点：</p><ol><li><strong>时间轴选中时</strong>：如果选中了具体的时间轴，任何对路径、形状或属性的更改都将<strong>自动在时间轴上生成关键帧</strong>。因此，我们建议不要在选中时间轴时创建素材。</li><li><strong>状态机选中时</strong>：如果选中了状态机，其表现与设计模式一致。创建素材、绑定或其他设计更改<strong>不会</strong>自动产生关键帧。这让你无需切换模式即可进行设计调整。我们建议在设计模式下进行重大改动，而仅在动画模式下添加如碰撞体 (hitboxes) 或布局调整等快速微调。</li></ol><p><a href="/docs/editor/fundamentals/overview">概览 (Overview)</a><a href="/docs/editor/fundamentals/artboards">画板 (Artboards)</a></p>',13)])])}const g=a(o,[["render",s]]);export{f as __pageData,g as default};
